<script setup>
import {computed,onMounted,onUnmounted,ref} from 'vue';import {useRoute} from 'vue-router';import QuestionCard from '../components/QuestionCard.vue';import ProgressBar from '../components/ProgressBar.vue';import QuizResult from '../components/QuizResult.vue';import {getDailyQuestions,saveAnswer,calculateScore,saveSession,generateRandomQuestions,getWrongQuestions,getBookmarkedQuestions} from '../utils/quizEngine';import {getBookmarks,setBookmarks} from '../utils/storage';import allQuestions from '../data/questions.json';import {formatDuration} from '../utils/dateUtils'
const route=useRoute(),category=ref(route.query.category||'Semua'),difficulty=ref('Semua'),current=ref(0),answers=ref({}),doubtful=ref([]),questions=ref([]),startedAt=ref(new Date().toISOString()),seconds=ref(0),result=ref(null),notice=ref(''),bookmarkVersion=ref(0);let timer
function load(){if(route.query.subcategory||route.query.mode||route.query.startId)return applyFilter();const data=getDailyQuestions({category:category.value});questions.value=data.questions;answers.value={...(data.answers||{})};doubtful.value=data.doubtful||[];startedAt.value=data.startedAt||new Date().toISOString();notice.value=data.notice||'';result.value=null;current.value=0}
function applyFilter(){let pool=category.value==='Semua'?allQuestions:allQuestions.filter(q=>q.kategori===category.value);if(route.query.subcategory)pool=pool.filter(q=>q.subkategori===route.query.subcategory);if(route.query.mode==='wrong'||difficulty.value==='Pernah salah')pool=getWrongQuestions().filter(q=>category.value==='Semua'||q.kategori===category.value);if(route.query.mode==='bookmark')pool=getBookmarkedQuestions().filter(q=>category.value==='Semua'||q.kategori===category.value);if(['Mudah','Sedang','Sulit'].includes(difficulty.value))pool=pool.filter(q=>q.tingkat_kesulitan===difficulty.value);questions.value=generateRandomQuestions(pool,50);if(route.query.startId){const i=questions.value.findIndex(q=>q.id===route.query.startId);if(i>0)questions.value.unshift(...questions.value.splice(i,1))}answers.value={};doubtful.value=[];startedAt.value=new Date().toISOString();result.value=null;current.value=0;notice.value=questions.value.length<50?`Soal tersedia ${questions.value.length} dari target 50.`:''}
function answer(key){const q=questions.value[current.value];answers.value={...answers.value,[q.id]:key};saveAnswer(q,key,'daily')}function bookmark(){const id=questions.value[current.value].id,b=getBookmarks();setBookmarks(b.includes(id)?b.filter(x=>x!==id):[...b,id]);bookmarkVersion.value++}function toggleDoubt(){const id=questions.value[current.value].id;doubtful.value=doubtful.value.includes(id)?doubtful.value.filter(x=>x!==id):[...doubtful.value,id]}function finish(){result.value=saveSession({title:'Latihan Harian',category:category.value,questions:questions.value,answers:answers.value,startedAt:startedAt.value,doubtful:doubtful.value})}const score=computed(()=>calculateScore(questions.value,answers.value)),q=computed(()=>questions.value[current.value]),bookmarks=computed(()=>{bookmarkVersion.value;return getBookmarks()});onMounted(()=>{load();timer=setInterval(()=>seconds.value++,1000)});onUnmounted(()=>clearInterval(timer))
</script>
<template><section class="page"><h1>Latihan Harian</h1><p class="lead">Jawaban tersimpan otomatis di perangkat.</p><div class="toolbar card"><select v-model="category"><option>Semua</option><option>SIMAK UI</option><option>LPDP</option><option>BTKV</option></select><select v-model="difficulty"><option>Semua</option><option>Mudah</option><option>Sedang</option><option>Sulit</option><option>Pernah salah</option></select><button class="btn" @click="applyFilter">Mulai / Terapkan</button><span class="pill">Timer {{formatDuration(seconds)}}</span></div><div v-if="notice" class="alert">{{notice}}</div><ProgressBar :value="score.answered" :max="questions.length||50" label="Jawaban tersimpan"/><QuizResult v-if="result" :result="result" @restart="load" @review="result=null"/><QuestionCard v-else-if="q" :question="q" :number="current+1" :total="questions.length" :selected="answers[q.id]" :show-answer="!!answers[q.id]" :bookmarked="bookmarks.includes(q.id)" :doubtful="doubtful.includes(q.id)" @answer="answer" @bookmark="bookmark" @doubtful="toggleDoubt" @prev="current=Math.max(0,current-1)" @next="current=Math.min(questions.length-1,current+1)" @finish="finish"/><div v-else class="card empty">Belum ada soal untuk filter ini. Pilih kategori lain.</div></section></template>
